/// Fills in the starting lists once per revision. Dishes that already hold
/// text are skipped, so a caterer edit always wins.
pub async fn backfill(pool: &SqlitePool) -> Result<(), sqlx::Error> {
    const INGREDIENTS_VERSION: &str = "1";

    let seeded: Option<String> =
        sqlx::query_scalar("SELECT value FROM settings WHERE key = 'ingredients_version'")
            .fetch_optional(pool)
            .await?;

    if seeded.as_deref() == Some(INGREDIENTS_VERSION) {
        return Ok(());
    }

    for (name, items) in INGREDIENTS {
        sqlx::query(
            "UPDATE menu_items SET ingredients = ?
             WHERE name = ? AND (ingredients IS NULL OR TRIM(ingredients) = '')",
        )
        .bind(items.join("\n"))
        .bind(*name)
        .execute(pool)
        .await?;
    }

    sqlx::query(
        "INSERT INTO settings (key, value) VALUES ('ingredients_version', ?)
         ON CONFLICT(key) DO UPDATE SET value = excluded.value",
    )
    .bind(INGREDIENTS_VERSION)
    .execute(pool)
    .await?;

    Ok(())
}
